CREATE TABLE t3 (c1 TEXT CHECK ((SELECT * LIMIT EXISTS (SELECT * INTERSECT SELECT * FROM t1 WHERE CURRENT_DATE GROUP BY FALSE WINDOW w1 AS () ORDER BY CURRENT_TIMESTAMP COLLATE NOCASE ASC NULLS FIRST), RAISE(IGNORE)))) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS p(a UNIQUE);
SELECT p.a FROM p JOIN p q ON 3 = p.a NATURAL JOIN p WHERE p.a IN((SELECT(SELECT coalesce(lead(2) OVER(), SUM(a))) FROM p d WHERE p.a));